abstract class Shape {
    abstract double area();
    void describe() { System.out.println("To jest " + getClass().getSimpleName() + " o polu " + area()); }
}
class Circle extends Shape { double r; Circle(double r) { this.r = r; } double area() { return Math.PI * r * r; } }
class Square extends Shape { double side; Square(double s) { side = s; } double area() { return side * side; } }

public static void main(String[] args) {
    new Circle(3).describe();
    new Square(4).describe();
}

