abstract class SortStrategy {
    abstract void sort(int[] arr);
    abstract String name();
    void sortAndPrint(int[] arr) { sort(arr); System.out.println(name() + ": " + java.util.Arrays.toString(arr)); }
}
class BubbleSort extends SortStrategy {
    void sort(int[] arr) { for (int i=0;i<arr.length;i++) for (int j=0;j<arr.length-1-i;j++) if (arr[j]>arr[j+1]) { int t=arr[j]; arr[j]=arr[j+1]; arr[j+1]=t; } }
    String name() { return "BubbleSort"; }
}

public static void main(String[] args) {
    new BubbleSort().sortAndPrint(new int[]{5,2,8,1,9});
}

abstract class Validator<T> {
    abstract boolean isValid(T value);
    void validate(T value) { if (!isValid(value)) throw new IllegalArgumentException("Niepoprawna wartosc: " + value); }
}
class PositiveNumberValidator extends Validator<Integer> { boolean isValid(Integer v) { return v > 0; } }

public static void main(String[] args) {
    Validator<Integer> v = new PositiveNumberValidator();
    v.validate(5);
    try { v.validate(-1); } catch (IllegalArgumentException e) { System.out.println("Zlapano: " + e.getMessage()); }
}

abstract class NumberRange {
