    abstract int[] generate();
    void print() { System.out.println(java.util.Arrays.toString(generate())); }
}
class EvenNumbers extends NumberRange {
    EvenNumbers(int s, int e) { super(s, e); }
    int[] generate() { return java.util.stream.IntStream.rangeClosed(start, end).filter(n -> n % 2 == 0).toArray(); }
}

public static void main(String[] args) {
    new EvenNumbers(0, 20).print();
}

