abstract class PipelineStep {
    PipelineStep next;
    abstract String process(String input);
    PipelineStep then(PipelineStep n) { next = n; return n; }
    String execute(String input) {
        String result = process(input);
        return next != null ? next.execute(result) : result;
    }
}
class TrimStep extends PipelineStep { String process(String s) { return s.trim(); } }
class UpperCaseStep extends PipelineStep { String process(String s) { return s.toUpperCase(); } }

public static void main(String[] args) {
    PipelineStep trim = new TrimStep();
    trim.then(new UpperCaseStep());
    System.out.println(trim.execute(" hello world "));
}

abstract class Command { boolean executed; abstract void execute(); abstract void undo(); boolean wasExecuted() { return executed; } }
class AddTextCommand extends Command { void execute() { executed = true; System.out.println("Dodano tekst"); } void undo() { System.out.println("Cofnieto dodanie"); } }
class CommandHistory {
    java.util.List<Command> history = new java.util.ArrayList<>();
    void run(Command c) { c.execute(); history.add(c); }
    void undoLast() { if (!history.isEmpty()) history.remove(history.size()-1).undo(); }
}

public static void main(String[] args) {
    CommandHistory h = new CommandHistory();
    h.run(new AddTextCommand());
    h.undoLast();
}

abstract class Repository<T> {
    abstract void save(T item); abstract T findById(int id); abstract void delete(int id);
    void saveAndLog(T item) { save(item); System.out.println("Saved: " + item); }
}
class UserRepository extends Repository<String> {
    java.util.Map<Integer, String> data = new java.util.HashMap<>();
    void save(String item) { data.put(data.size(), item); }
    String findById(int id) { return data.get(id); }
    void delete(int id) { data.remove(id); }
}

public static void main(String[] args) {
    new UserRepository().saveAndLog("Jan Kowalski");
}

abstract class EventListener {
