    abstract String[] getListenedTypes();
    boolean listensTo(String type) { for (String t : getListenedTypes()) if (t.equals(type)) return true; return false; }
}
class ClickListener extends EventListener {
    void onEvent(String type, Object data) { System.out.println("Kliknieto: " + data); }
    String[] getListenedTypes() { return new String[]{"click"}; }
}

public static void main(String[] args) {
    ClickListener cl = new ClickListener();
    if (cl.listensTo("click")) cl.onEvent("click", "przycisk1");
}

abstract class QueryBuilder<T extends QueryBuilder<T>> {
    String conditions = "";
    abstract T self();
    T where(String c) { conditions += " WHERE " + c; return self(); }
    abstract String build();
}
class SelectBuilder extends QueryBuilder<SelectBuilder> {
    SelectBuilder self() { return this; }
    String build() { return "SELECT *" + conditions; }
}

public static void main(String[] args) {
    System.out.println(new SelectBuilder().where("id=1").build());
}

abstract class CompressionAlgorithm {
    abstract byte[] compress(String data);
    double compressionRatio(String data) { return (double) data.length() / compress(data).length; }
}
class NoCompression extends CompressionAlgorithm { byte[] compress(String data) { return data.getBytes(); } }

public static void main(String[] args) {
    System.out.println(new NoCompression().compressionRatio("aaaaabbbbbccccc"));
}

abstract class Component { abstract int getSize(); }
class FileComp extends Component { int size; FileComp(int s) { size = s; } int getSize() { return size; } }
class Directory extends Component {
    Component[] children;
    Directory(Component[] c) { children = c; }
    int getSize() { int total = 0; for (Component c : children) total += c.getSize(); return total; }
}

public static void main(String[] args) {
    Directory dir = new Directory(new Component[]{ new FileComp(100), new FileComp(200) });
    System.out.println(dir.getSize());
}

abstract class Cache<K, V> {
    abstract void put(K key, V value); abstract V get(K key);
    V getOrCompute(K key, V defaultValue) { V v = get(key); return v != null ? v : defaultValue; }
}
class SimpleCache extends Cache<String, Integer> {
    java.util.Map<String, Integer> data = new java.util.HashMap<>();
    void put(String k, Integer v) { data.put(k, v); }
    Integer get(String k) { return data.get(k); }
}

public static void main(String[] args) {
    SimpleCache c = new SimpleCache();
    System.out.println(c.getOrCompute("brak", -1));
}

abstract class NetworkProtocol {
    final void communicate(String message) { handshake(); send(message); receive(); close(); }
    abstract void handshake(); abstract void send(String msg); abstract String receive(); abstract void close();
}
class HttpProtocol extends NetworkProtocol {
    void handshake() { System.out.println("HTTP handshake"); }
    void send(String msg) { System.out.println("Wysylanie: " + msg); }
    String receive() { System.out.println("Odbieranie odpowiedzi"); return "200 OK"; }
    void close() { System.out.println("Zamykanie polaczenia"); }
}

public static void main(String[] args) {
    new HttpProtocol().communicate("GET /");
}

abstract class TreeNode { int value; TreeNode(int v) { value = v; } abstract int sum(); }
class Leaf extends TreeNode { Leaf(int v) { super(v); } int sum() { return value; } }
class Branch extends TreeNode {
    TreeNode left, right;
    Branch(int v, TreeNode l, TreeNode r) { super(v); left = l; right = r; }
    int sum() { return value + left.sum() + right.sum(); }
}

public static void main(String[] args) {
    Branch tree = new Branch(1, new Leaf(2), new Leaf(3));
    System.out.println(tree.sum()); // 6
}

abstract class TuringMachine {
    abstract char[] getAlphabet();
    abstract void transition(char symbol);
    void run(char[] tape) { for (char c : tape) transition(c); }
}
class PalindromeChecker extends TuringMachine {
    StringBuilder seen = new StringBuilder();
    char[] getAlphabet() { return new char[]{'0','1'}; }
    void transition(char symbol) { seen.append(symbol); }
}

public static void main(String[] args) {
    PalindromeChecker pc = new PalindromeChecker();
    pc.run("1001".toCharArray());
    String s = pc.seen.toString();
    System.out.println(s.equals(new StringBuilder(s).reverse().toString()));
}
